// Check news feed freshness and build alert status
// All ES5/ASCII -- no template literals, no Unicode special chars
var item = $input.item.json;
var now = new Date();
var alertNeeded = false;
var alertReason = '';
var alertSeverity = 'warn'; // 'warn' or 'crit'

// Check for HTTP error (continueOnFail passes error as item.error)
if (item.error || $input.item.pairedItem === undefined) {
  alertNeeded = true;
  alertReason = 'AlphaForgeAI /api/news endpoint is unreachable or returned an error.';
  alertSeverity = 'crit';
} else {
  var generatedAt = item.generated_at || '';
  if (!generatedAt) {
    alertNeeded = true;
    alertReason = 'News feed response missing generated_at field. Feed may be empty or broken.';
    alertSeverity = 'warn';
  } else {
    // Parse timestamp
    var ts = new Date(generatedAt.replace('Z', '+00:00'));
    var ageMinutes = Math.floor((now - ts) / 60000);
    // Alert if feed is older than 8 hours (480 minutes)
    // News workflow runs 4x/day so max gap is ~6h; 8h allows buffer
    if (ageMinutes > 480) {
      alertNeeded = true;
      alertReason = 'News feed has not been updated in ' + ageMinutes + ' minutes (>' + Math.floor(ageMinutes/60) + 'h). Last update: ' + generatedAt;
      alertSeverity = 'warn';
    }
  }
}

return [{
  json: {
    alertNeeded: alertNeeded,
    alertReason: alertReason,
    alertSeverity: alertSeverity,
    checkedAt: now.toISOString(),
    generatedAt: (item && item.generated_at) ? item.generated_at : 'unknown',
    totalArticles: (item && item.total) ? item.total : 0
  }
}];

// Build Discord embed payload
var d = $input.item.json;
var isCrit = (d.alertSeverity === 'crit');
var color = isCrit ? 15158332 : 16776960; // red or yellow
var emoji = isCrit ? ':red_circle:' : ':warning:';
var title = emoji + ' AlphaForgeAI News Alert';
var desc = d.alertReason + '\n\nChecked at: ' + d.checkedAt;

return [{
  json: {
    payload: JSON.stringify({
      embeds: [{
        title: title,
        description: desc,
        color: color,
        timestamp: d.checkedAt
      }]
    })
  }
}];
